cd /work/output/artifacts/skill-flow-customer-escalation/CustomerEscalation/CustomerEscalation \
  && OUTLOOK_CONN="75dfafb4-3717-470c-a5f6-bdc144757a67" \
  && OUTLOOK_FOLDER="5da18ec0-7de1-4e57-aaf1-ddc8a369c199" \
  && SLACK_CONN="849e85d8-1aa9-4d52-8bbd-20041c8f05d8" \
  && SLACK_FOLDER="5da18ec0-7de1-4e57-aaf1-ddc8a369c199" \
  && INBOX_ID="AAMkAGNiNDVjZmJmLTczOTEtNDQ2MS04Njc2LTUwM2I3ZDgxOWQwMAAuAAAAAAAJJRkzOJfsTKZfQqhMUHzlAQAJDKUrZhoLQZ5wELpOfJPCAAAAAAEMAAA=" \
  && python3 << 'PYEOF'
import json

# Slack - Notify VIP
slack_detail = {
    "connectionId": "849e85d8-1aa9-4d52-8bbd-20041c8f05d8",
    "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
    "method": "POST",
    "endpoint": "/send_message_to_channel_v2",
    "objectName": "send_message_to_channel_v2",
    "bodyParameters": {
        "channel": "C01H4SPS77W",
        "messageToSend": "=js:\"[URGENT VIP] New escalation from: \" + $vars.classifyVip1.output.senderAddress + \" | Subject: \" + ($vars.emailReceived1.output.subject || \"(no subject)\")"
    },
    "queryParameters": {
        "send_as": "bot"
    }
}
with open("/tmp/slack_detail.json", "w") as f:
    json.dump(slack_detail, f)

# Outlook reply VIP ack
reply_vip_detail = {
    "connectionId": "75dfafb4-3717-470c-a5f6-bdc144757a67",
    "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
    "method": "POST",
    "endpoint": "/ReplyToEmailV2",
    "objectName": "ReplyToEmailV2",
    "pathParameters": {
        "id": "=js:$vars.emailReceived1.output.id"
    },
    "queryParameters": {
        "saveAsDraft": False
    },
    "bodyParameters": {
        "body": "=js:\"Thank you for reaching out. Your request has been flagged as high-priority and our senior support team is on it. You will hear back from us within 2 hours. We appreciate your patience.\""
    }
}
with open("/tmp/reply_vip_detail.json", "w") as f:
    json.dump(reply_vip_detail, f)

# Outlook reply standard ticket
reply_std_detail = {
    "connectionId": "75dfafb4-3717-470c-a5f6-bdc144757a67",
    "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
    "method": "POST",
    "endpoint": "/ReplyToEmailV2",
    "objectName": "ReplyToEmailV2",
    "pathParameters": {
        "id": "=js:$vars.emailReceived1.output.id"
    },
    "queryParameters": {
        "saveAsDraft": False
    },
    "bodyParameters": {
        "body": "=js:$vars.generateTicket1.output.replyBody"
    }
}
with open("/tmp/reply_std_detail.json", "w") as f:
    json.dump(reply_std_detail, f)

print("Detail files written OK")
PYEOF
